            if os.path.islink(path) or not os.path.isfile(path):
                result.append((' M',name)); continue
            with open(path,'r',encoding='utf-8') as f: contents=f.read()
            if contents != entry.get('contents','') or stat.S_IMODE(os.stat(path).st_mode)!=entry.get('perm',0o644):
                result.append((' M',name))
        except (OSError,UnicodeError):
            result.append((' M',name))
    return result


def handle(command, source, destination, args=()):
    style='relative'; selectors=[]; i=0
